import { test, expect } from '@playwright/test';

test.describe('Responsive Design - Landscape Orientation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-app-url.com');
    await page.setViewportSize({ width: 800, height: 600 }); // Landscape orientation
  });

  test('should display header correctly in landscape orientation', async ({ page }) => {
    const header = page.getByRole('heading', { name: /app header/i });
    await expect(header).toBeVisible();
    await expect(header).toHaveCSS('font-size', '24px'); // Example assertion
  });

  test('should display main content correctly in landscape orientation', async ({ page }) => {
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();
    await expect(mainContent).toHaveCSS('flex-direction', 'row'); // Example assertion
  });
});
